package org.eclipse.rdf4j.model.util;

import java.util.HashMap;
import java.util.Map;
import java.util.function.Supplier;

import org.eclipse.rdf4j.model.BNode;
import org.eclipse.rdf4j.model.Resource;
import org.eclipse.rdf4j.model.Statement;
import org.eclipse.rdf4j.model.TripleTerm;
import org.eclipse.rdf4j.model.vocabulary.RDF;

/**
 * Conversion context used during RDF 1.2, RDF 1.2 Basic and RDF 1.1 transformations.
 * <p>
 * Stores the mapping from RDF 1.2 {@link TripleTerm}s to the blank nodes that represent them in RDF 1.2 basic and RDF
 * 1.1 proposition forms. Reusing the same blank node for repeated occurrences of a triple term in a given graph,
 * assigning unique blank nodes to each among the default and all named graphs. Preserves the graph structure and is
 * more efficient.
 */
public class RDFVersionsConversionContext {

	// null key = default graph
	private final Map<Resource, Map<TripleTerm, BNode>> tripleTermToBNodePerGraph = new HashMap<>();
	private final Map<Resource, InputGraphType> inputGraphTypes = new HashMap<>();

	void observe(Statement statement) {
		InputGraphType inputGraphType = getInputGraphType(statement);
		if (inputGraphType == null) {
			return;
		}

		InputGraphType previous = inputGraphTypes.putIfAbsent(statement.getContext(), inputGraphType);
		if (previous != null && previous != inputGraphType) {
			throw new IllegalArgumentException(
					"Cannot basic-encode a graph containing both triple terms and blank-node rdf:PropositionForm statements");
		}
	}

	private static InputGraphType getInputGraphType(Statement statement) {
		if (statement.getObject().isTripleTerm()) {
			return InputGraphType.FULL;
		}
		if (statement.getSubject() instanceof BNode && RDF.TYPE.equals(statement.getPredicate())
				&& RDF.PROPOSITION_FORM.equals(statement.getObject())) {
			return InputGraphType.BASIC;
		}
		return null;
	}

	public BNode getOrCreate(Resource context, TripleTerm tt, Supplier<BNode> gen) {
		Map<TripleTerm, BNode> graphMap = tripleTermToBNodePerGraph.computeIfAbsent(context, _ -> new HashMap<>());
		return graphMap.computeIfAbsent(tt, _ -> gen.get());
	}

	public BNode getBNodeForTripleTerm(Resource context, TripleTerm tt) {
		Map<TripleTerm, BNode> graphMap = tripleTermToBNodePerGraph.get(context);
		return graphMap == null ? null : graphMap.get(tt);
	}

	private enum InputGraphType {
		FULL,
		BASIC
	}
}
